class _UniffiConverterBool:
    @classmethod
    def check_lower(cls, value):
        return not not value

    @classmethod
    def lower(cls, value):
        return 1 if value else 0

    @staticmethod
    def lift(value):
        return value != 0

    @classmethod
    def read(cls, buf):
        return cls.lift(buf.read_u8())

    @classmethod
    def write(cls, value, buf):
        buf.write_u8(value)

class _UniffiConverterString:
    @staticmethod
    def check_lower(value):
        if not isinstance(value, str):
            raise TypeError("argument must be str, not {}".format(type(value).__name__))
        return value

    @staticmethod
    def read(buf):
        size = buf.read_i32()
        if size < 0:
            raise InternalError("Unexpected negative string length")
        utf8_bytes = buf.read(size)
        return utf8_bytes.decode("utf-8")

    @staticmethod
    def write(value, buf):
        utf8_bytes = value.encode("utf-8")
        buf.write_i32(len(utf8_bytes))
        buf.write(utf8_bytes)

    @staticmethod
    def lift(buf):
        with buf.consume_with_stream() as stream:
            return stream.read(stream.remaining()).decode("utf-8")

    @staticmethod
    def lower(value):
        with _UniffiRustBuffer.alloc_with_builder() as builder:
            builder.write(value.encode("utf-8"))
            return builder.finalize()




class Card:
    title: "str"
    value: "str"
    description: "str"
    card_type: "CardType"
    def __init__(self, *, title: "str", value: "str", description: "str", card_type: "CardType"):
        self.title = title
        self.value = value
        self.description = description
        self.card_type = card_type

    def __str__(self):
        return "Card(title={}, value={}, description={}, card_type={})".format(self.title, self.value, self.description, self.card_type)

    def __eq__(self, other):
        if self.title != other.title:
            return False
        if self.value != other.value:
            return False
        if self.description != other.description:
            return False
        if self.card_type != other.card_type:
            return False
        return True

