class AudioEngineError:
    def __init__(self):
        raise RuntimeError("AudioEngineError cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    class STREAM_BUILD_ERROR:
        def __init__(self, *values):
            if len(values) != 1:
                raise TypeError(f"Expected 1 arguments, found {len(values)}")
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

        def __str__(self):
            return f"AudioEngineError.STREAM_BUILD_ERROR{self._values!r}"

        def __eq__(self, other):
            if not other.is_STREAM_BUILD_ERROR():
                return False
            return self._values == other._values
    class BUFFER_OVERFILL:

        def __init__(self,):
            pass

        def __str__(self):
            return "AudioEngineError.BUFFER_OVERFILL()".format()

        def __eq__(self, other):
            if not other.is_BUFFER_OVERFILL():
                return False
            return True
    
    

    # For each variant, we have `is_NAME` and `is_name` methods for easily checking
    # whether an instance is that variant.
    def is_STREAM_BUILD_ERROR(self) -> bool:
        return isinstance(self, AudioEngineError.STREAM_BUILD_ERROR)
    def is_stream_build_error(self) -> bool:
        return isinstance(self, AudioEngineError.STREAM_BUILD_ERROR)
    def is_BUFFER_OVERFILL(self) -> bool:
        return isinstance(self, AudioEngineError.BUFFER_OVERFILL)
    def is_buffer_overfill(self) -> bool:
        return isinstance(self, AudioEngineError.BUFFER_OVERFILL)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
AudioEngineError.STREAM_BUILD_ERROR = type("AudioEngineError.STREAM_BUILD_ERROR", (AudioEngineError.STREAM_BUILD_ERROR, AudioEngineError,), {})  # type: ignore
AudioEngineError.BUFFER_OVERFILL = type("AudioEngineError.BUFFER_OVERFILL", (AudioEngineError.BUFFER_OVERFILL, AudioEngineError,), {})  # type: ignore




class _UniffiConverterTypeAudioEngineError(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return AudioEngineError.STREAM_BUILD_ERROR(
                _UniffiConverterString.read(buf),
            )
        if variant == 2:
            return AudioEngineError.BUFFER_OVERFILL(
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_STREAM_BUILD_ERROR():
            _UniffiConverterString.check_lower(value._values[0])
            return
        if value.is_BUFFER_OVERFILL():
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_STREAM_BUILD_ERROR():
            buf.write_i32(1)
            _UniffiConverterString.write(value._values[0], buf)
        if value.is_BUFFER_OVERFILL():
            buf.write_i32(2)







