class Notes:
    def __init__(self):
        raise RuntimeError("Notes cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    class START:
        def __init__(self, *values):
            if len(values) != 1:
                raise TypeError(f"Expected 1 arguments, found {len(values)}")
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

        def __str__(self):
            return f"Notes.START{self._values!r}"

        def __eq__(self, other):
            if not other.is_START():
                return False
            return self._values == other._values
    class END:
        def __init__(self, *values):
            if len(values) != 1:
                raise TypeError(f"Expected 1 arguments, found {len(values)}")
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

        def __str__(self):
            return f"Notes.END{self._values!r}"

        def __eq__(self, other):
            if not other.is_END():
                return False
            return self._values == other._values
    

    # For each variant, we have `is_NAME` and `is_name` methods for easily checking
    # whether an instance is that variant.
    def is_START(self) -> bool:
        return isinstance(self, Notes.START)
    def is_start(self) -> bool:
        return isinstance(self, Notes.START)
    def is_END(self) -> bool:
        return isinstance(self, Notes.END)
    def is_end(self) -> bool:
        return isinstance(self, Notes.END)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
Notes.START = type("Notes.START", (Notes.START, Notes,), {})  # type: ignore
Notes.END = type("Notes.END", (Notes.END, Notes,), {})  # type: ignore




class _UniffiConverterTypeNotes(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return Notes.START(
                _UniffiConverterTypeStartNote.read(buf),
            )
        if variant == 2:
            return Notes.END(
                _UniffiConverterTypeEndNote.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_START():
            _UniffiConverterTypeStartNote.check_lower(value._values[0])
            return
        if value.is_END():
            _UniffiConverterTypeEndNote.check_lower(value._values[0])
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_START():
            buf.write_i32(1)
            _UniffiConverterTypeStartNote.write(value._values[0], buf)
        if value.is_END():
            buf.write_i32(2)
            _UniffiConverterTypeEndNote.write(value._values[0], buf)







